"use client";

import { createClient, type Session } from "@supabase/supabase-js";
import { useCallback, useEffect, useMemo, useState } from "react";
import styles from "./platform.module.css";

type Theme = "light" | "dark";
type Lang = "en" | "ar";
type View = "home" | "opportunities" | "tenders" | "quotations" | "orders" | "warehouse" | "supply" | "invoices" | "collection" | "management" | "ai" | "products";
type Organization = { id:string; name:string; slug:string; industry:string|null; country:string; currency:string; onboarding_status:string };
type Membership = { org_id:string; role:string };
type Product = { id:string; org_id:string; sku:string; name:string; category:string|null; brand:string|null; stock_qty:number; reserved_qty:number; unit_cost:number|null; sale_price:number|null; active:boolean };
type Opportunity = { id:string; org_id:string; external_ref:string|null; buyer:string; title:string; source:string; source_url:string|null; published_at:string|null; deadline_at:string|null; estimated_value:number|null; match_score:number; bid_score:number; matched_items:number; total_items:number; status:string; recommendation:string|null; summary:string|null; reasons:unknown };
type Tender = { id:string; org_id:string; opportunity_id:string|null; ref:string; buyer:string; title:string; deadline_at:string|null; estimated_value:number|null; readiness:number; missing_count:number; owner_name:string|null; status:string; bid_decision:string; documents:unknown };
type Quotation = { id:string; org_id:string; tender_id:string|null; ref:string; customer_name:string; amount:number; items_count:number; verified_count:number; error_count:number; status:string; valid_until:string|null; next_action:string|null };
type Order = { id:string; org_id:string; tender_id:string|null; quotation_id:string|null; ref:string; customer_name:string; amount:number; items_count:number; ready_count:number; missing_count:number; due_at:string|null; status:string };
type Supply = { id:string; org_id:string; order_id:string; sku:string|null; item_name:string; qty:number; allocated_qty:number; source:string|null; status:string; due_at:string|null };
type Invoice = { id:string; org_id:string; order_id:string|null; ref:string; customer_name:string; amount:number; issued_at:string; due_at:string|null; paid_amount:number; status:string };
type Collection = { id:string; org_id:string; invoice_id:string; owner_name:string|null; next_action:string|null; status:string; last_contact_at:string|null; promised_at:string|null; note:string|null };
type Alert = { id:string; org_id:string; type:string; severity:string; entity_type:string|null; entity_id:string|null; title:string; detail:string|null; action_label:string|null; status:string; created_at:string };
type Activity = { id:string; org_id:string; activity_type:string; entity_type:string|null; entity_id:string|null; summary:string; created_at:string };
type WorkspaceData = { products:Product[]; opportunities:Opportunity[]; tenders:Tender[]; quotations:Quotation[]; orders:Order[]; supply:Supply[]; invoices:Invoice[]; collections:Collection[]; alerts:Alert[]; activities:Activity[] };

const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!);
const emptyData:WorkspaceData={products:[],opportunities:[],tenders:[],quotations:[],orders:[],supply:[],invoices:[],collections:[],alerts:[],activities:[]};

const nav:Array<{id:View;icon:string;en:string;ar:string;divider?:boolean}>=[
  {id:"home",icon:"◫",en:"Overview",ar:"نظرة عامة"},
  {id:"opportunities",icon:"✦",en:"Opportunities",ar:"الفرص"},
  {id:"tenders",icon:"◇",en:"Tenders",ar:"المناقصات"},
  {id:"quotations",icon:"▤",en:"Quotations",ar:"عروض الأسعار"},
  {id:"orders",icon:"▦",en:"Orders",ar:"الطلبات"},
  {id:"warehouse",icon:"▧",en:"Warehouse",ar:"المستودع"},
  {id:"supply",icon:"↗",en:"Supply",ar:"التوريد"},
  {id:"invoices",icon:"▱",en:"Invoices",ar:"الفواتير"},
  {id:"collection",icon:"◉",en:"Collection",ar:"التحصيل"},
  {id:"management",icon:"▥",en:"Management",ar:"الإدارة",divider:true},
  {id:"ai",icon:"✦",en:"Ask LabNarrative",ar:"اسأل LabNarrative"},
  {id:"products",icon:"◎",en:"Products",ar:"المنتجات"},
];

const sum=(values:number[])=>values.reduce((a,b)=>a+(Number.isFinite(b)?b:0),0);
const num=(value:number)=>new Intl.NumberFormat("en-US",{maximumFractionDigits:0}).format(value||0);
const dateLabel=(value:string|null)=>{if(!value)return"—";const d=new Date(value);return Number.isNaN(d.getTime())?"—":new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric"}).format(d)};
const daysUntil=(value:string|null)=>{if(!value)return 9999;return Math.ceil((new Date(value).getTime()-Date.now())/86400000)};
const reasons=(value:unknown):string[]=>Array.isArray(value)?value.filter((x):x is string=>typeof x==="string"):[];
const titleCase=(value:string)=>String(value||"").replaceAll("_"," ").replace(/\b\w/g,(c)=>c.toUpperCase());

export default function PlatformClient(){
  const[theme,setTheme]=useState<Theme>("light"),[lang,setLang]=useState<Lang>("en"),[active,setActive]=useState<View>("home");
  const[session,setSession]=useState<Session|null>(null),[authReady,setAuthReady]=useState(false),[authMode,setAuthMode]=useState<"signin"|"signup">("signin");
  const[email,setEmail]=useState(""),[password,setPassword]=useState(""),[authBusy,setAuthBusy]=useState(false),[authError,setAuthError]=useState("");
  const[memberships,setMemberships]=useState<Membership[]>([]),[organizations,setOrganizations]=useState<Organization[]>([]),[selectedOrgId,setSelectedOrgId]=useState("");
  const[data,setData]=useState<WorkspaceData>(emptyData),[loading,setLoading]=useState(false),[notice,setNotice]=useState("");
  const[orgName,setOrgName]=useState(""),[orgIndustry,setOrgIndustry]=useState("Scientific & Medical Distribution"),[orgCountry,setOrgCountry]=useState("Saudi Arabia"),[creatingOrg,setCreatingOrg]=useState(false);
  const[showOpportunityForm,setShowOpportunityForm]=useState(false),[opBuyer,setOpBuyer]=useState(""),[opTitle,setOpTitle]=useState(""),[opDeadline,setOpDeadline]=useState(""),[opValue,setOpValue]=useState(""),[opMatch,setOpMatch]=useState("75");
  const[productSku,setProductSku]=useState(""),[productName,setProductName]=useState(""),[productStock,setProductStock]=useState("0"),[showProductForm,setShowProductForm]=useState(false),[uploading,setUploading]=useState(false);
  const[aiQuestion,setAiQuestion]=useState(""),[aiAnswer,setAiAnswer]=useState("");

  const T=(en:string,ar:string)=>lang==="ar"?ar:en;
  const notify=(message:string)=>{setNotice(message);window.setTimeout(()=>setNotice(""),2200)};

  const loadOrganizations=useCallback(async(activeSession:Session)=>{
    const{data:memberRows,error:memberError}=await supabase.from("ln_organization_members").select("org_id,role").eq("status","active");
    if(memberError){setAuthError(memberError.message);return}
    const ms=(memberRows??[]) as Membership[];setMemberships(ms);
    if(!ms.length){setOrganizations([]);setSelectedOrgId("");return}
    const ids=ms.map((m)=>m.org_id);
    const{data:orgRows,error:orgError}=await supabase.from("ln_organizations").select("id,name,slug,industry,country,currency,onboarding_status").in("id",ids).order("created_at",{ascending:true});
    if(orgError){setAuthError(orgError.message);return}
    const os=(orgRows??[]) as Organization[];setOrganizations(os);
    setSelectedOrgId((current)=>current&&os.some((o)=>o.id===current)?current:os[0]?.id??"");
    void activeSession;
  },[]);

  const loadWorkspace=useCallback(async(orgId:string)=>{
    if(!orgId)return;setLoading(true);
    const[p,op,t,q,o,s,i,c,a,act]=await Promise.all([
      supabase.from("ln_products").select("id,org_id,sku,name,category,brand,stock_qty,reserved_qty,unit_cost,sale_price,active").eq("org_id",orgId).order("name"),
      supabase.from("ln_opportunities").select("id,org_id,external_ref,buyer,title,source,source_url,published_at,deadline_at,estimated_value,match_score,bid_score,matched_items,total_items,status,recommendation,summary,reasons").eq("org_id",orgId).order("deadline_at",{ascending:true,nullsFirst:false}),
      supabase.from("ln_tenders").select("id,org_id,opportunity_id,ref,buyer,title,deadline_at,estimated_value,readiness,missing_count,owner_name,status,bid_decision,documents").eq("org_id",orgId).order("deadline_at",{ascending:true,nullsFirst:false}),
      supabase.from("ln_quotations").select("id,org_id,tender_id,ref,customer_name,amount,items_count,verified_count,error_count,status,valid_until,next_action").eq("org_id",orgId).order("created_at",{ascending:false}),
      supabase.from("ln_orders").select("id,org_id,tender_id,quotation_id,ref,customer_name,amount,items_count,ready_count,missing_count,due_at,status").eq("org_id",orgId).order("due_at",{ascending:true,nullsFirst:false}),
      supabase.from("ln_supply").select("id,org_id,order_id,sku,item_name,qty,allocated_qty,source,status,due_at").eq("org_id",orgId).order("due_at",{ascending:true,nullsFirst:false}),
      supabase.from("ln_invoices").select("id,org_id,order_id,ref,customer_name,amount,issued_at,due_at,paid_amount,status").eq("org_id",orgId).order("due_at",{ascending:true,nullsFirst:false}),
      supabase.from("ln_collections").select("id,org_id,invoice_id,owner_name,next_action,status,last_contact_at,promised_at,note").eq("org_id",orgId).order("created_at",{ascending:false}),
      supabase.from("ln_alerts").select("id,org_id,type,severity,entity_type,entity_id,title,detail,action_label,status,created_at").eq("org_id",orgId).eq("status","open").order("created_at",{ascending:false}),
      supabase.from("ln_activity_log").select("id,org_id,activity_type,entity_type,entity_id,summary,created_at").eq("org_id",orgId).order("created_at",{ascending:false}).limit(30),
    ]);
    const err=p.error||op.error||t.error||q.error||o.error||s.error||i.error||c.error||a.error||act.error;
    if(err)notify(err.message);
    setData({products:(p.data??[]) as Product[],opportunities:(op.data??[]) as Opportunity[],tenders:(t.data??[]) as Tender[],quotations:(q.data??[]) as Quotation[],orders:(o.data??[]) as Order[],supply:(s.data??[]) as Supply[],invoices:(i.data??[]) as Invoice[],collections:(c.data??[]) as Collection[],alerts:(a.data??[]) as Alert[],activities:(act.data??[]) as Activity[]});
    setLoading(false);
  },[]);

  useEffect(()=>{const saved=(localStorage.getItem("labnarrative-platform-theme") as Theme|null);if(saved==="dark"||saved==="light")setTheme(saved);supabase.auth.getSession().then(({data:s})=>{setSession(s.session);setAuthReady(true);if(s.session)void loadOrganizations(s.session)});const{data:{subscription}}=supabase.auth.onAuthStateChange((_event,next)=>{setSession(next);setAuthReady(true);if(next)void loadOrganizations(next);else{setOrganizations([]);setSelectedOrgId("");setData(emptyData)}});return()=>subscription.unsubscribe()},[loadOrganizations]);
  useEffect(()=>{if(session&&selectedOrgId)void loadWorkspace(selectedOrgId)},[session,selectedOrgId,loadWorkspace]);

  const selectedOrg=organizations.find((o)=>o.id===selectedOrgId)??null;
  const currentRole=memberships.find((m)=>m.org_id===selectedOrgId)?.role??"viewer";
  const money=(value:number)=>new Intl.NumberFormat("en-SA",{style:"currency",currency:selectedOrg?.currency||"SAR",maximumFractionDigits:0}).format(value||0);
  const receivable=sum(data.invoices.map((x)=>Math.max(0,Number(x.amount)-Number(x.paid_amount))));
  const overdue=sum(data.invoices.filter((x)=>x.status==="overdue"||(x.due_at&&daysUntil(x.due_at)<0&&x.status!=="paid")).map((x)=>Math.max(0,Number(x.amount)-Number(x.paid_amount))));
  const opportunityValue=sum(data.opportunities.filter((x)=>!["no_bid","archived"].includes(x.status)).map((x)=>Number(x.estimated_value||0)));
  const tenderValue=sum(data.tenders.filter((x)=>!["lost","cancelled"].includes(x.status)).map((x)=>Number(x.estimated_value||0)));
  const wonValue=sum(data.orders.map((x)=>Number(x.amount||0)));
  const cash30=sum(data.invoices.filter((x)=>x.status!=="paid"&&x.due_at&&daysUntil(x.due_at)>=0&&daysUntil(x.due_at)<=30).map((x)=>Math.max(0,Number(x.amount)-Number(x.paid_amount))));
  const highMatch=data.opportunities.filter((x)=>x.status!=="bid"&&x.match_score>=80).sort((a,b)=>b.match_score-a.match_score);
  const shortageProducts=data.products.filter((x)=>Number(x.stock_qty)-Number(x.reserved_qty)<=5);
  const riskySupply=data.supply.filter((x)=>Number(x.allocated_qty)<Number(x.qty)&&x.status!=="delivered");
  const currentView=nav.find((x)=>x.id===active)??nav[0];

  async function authenticate(){setAuthBusy(true);setAuthError("");try{if(authMode==="signin"){const{data:s,error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error||!s.session)throw error||new Error("Sign in failed.");}else{const{data:s,error}=await supabase.auth.signUp({email:email.trim(),password});if(error)throw error;if(!s.session){setAuthError("Account created. Check your email to confirm the address, then sign in.");setAuthMode("signin");}}}catch(e){setAuthError(e instanceof Error?e.message:"Authentication failed.")}finally{setAuthBusy(false)}}
  async function signOut(){await supabase.auth.signOut()}
  function toggleTheme(){setTheme((v)=>{const next=v==="light"?"dark":"light";localStorage.setItem("labnarrative-platform-theme",next);return next})}
  async function createOrganization(){if(!orgName.trim())return;setCreatingOrg(true);const{data:id,error}=await supabase.rpc("ln_create_organization",{p_name:orgName.trim(),p_industry:orgIndustry.trim()||null,p_country:orgCountry.trim()||"Saudi Arabia",p_currency:"SAR"});if(error)notify(error.message);else if(session){await loadOrganizations(session);if(id)setSelectedOrgId(String(id));notify("Workspace created")}setCreatingOrg(false)}
  async function refresh(){if(selectedOrgId)await loadWorkspace(selectedOrgId)}
  async function startBid(id:string){const{error}=await supabase.rpc("ln_start_bid",{p_opportunity_id:id});if(error)notify(error.message);else{notify("Bid workspace created");setActive("tenders");await refresh()}}
  async function createQuote(id:string){const{error}=await supabase.rpc("ln_create_quotation",{p_tender_id:id});if(error)notify(error.message);else{notify("Quotation created");setActive("quotations");await refresh()}}
  async function awardTender(id:string){const{error}=await supabase.rpc("ln_award_tender",{p_tender_id:id});if(error)notify(error.message);else{notify("Award recorded — order created");setActive("orders");await refresh()}}
  async function createInvoice(id:string){const{error}=await supabase.rpc("ln_create_invoice",{p_order_id:id});if(error)notify(error.message);else{notify("Invoice created");setActive("invoices");await refresh()}}
  async function markInvoicePaid(id:string){const{error}=await supabase.rpc("ln_mark_invoice_paid",{p_invoice_id:id});if(error)notify(error.message);else{notify("Payment recorded");await refresh()}}
  async function setTenderStatus(id:string,status:string){const{error}=await supabase.from("ln_tenders").update({status}).eq("id",id).eq("org_id",selectedOrgId);if(error)notify(error.message);else{notify("Tender updated");await refresh()}}
  async function setQuoteStatus(id:string,status:string){const{error}=await supabase.from("ln_quotations").update({status}).eq("id",id).eq("org_id",selectedOrgId);if(error)notify(error.message);else{notify("Quotation updated");await refresh()}}
  async function setOrderStatus(id:string,status:string){const{error}=await supabase.from("ln_orders").update({status}).eq("id",id).eq("org_id",selectedOrgId);if(error)notify(error.message);else{notify("Order updated");await refresh()}}
  async function setSupplyStatus(id:string,status:string){const{error}=await supabase.from("ln_supply").update({status,allocated_qty:status==="delivered"?data.supply.find((x)=>x.id===id)?.qty:undefined}).eq("id",id).eq("org_id",selectedOrgId);if(error)notify(error.message);else{notify("Supply updated");await refresh()}}
  async function addOpportunity(){if(!opBuyer.trim()||!opTitle.trim()||!selectedOrgId)return;const match=Math.max(0,Math.min(100,Number(opMatch)||0));const{error}=await supabase.from("ln_opportunities").insert({org_id:selectedOrgId,buyer:opBuyer.trim(),title:opTitle.trim(),source:"manual",deadline_at:opDeadline?new Date(`${opDeadline}T12:00:00`).toISOString():null,estimated_value:Number(opValue)||null,match_score:match,bid_score:Math.max(0,match-5),status:"discovered",recommendation:match>=80?"BID":match>=60?"REVIEW":"NO-BID",summary:"Manually added opportunity. Add product-line intelligence as evidence becomes available.",reasons:["Manual V1 opportunity record"]});if(error)notify(error.message);else{setOpBuyer("");setOpTitle("");setOpDeadline("");setOpValue("");setShowOpportunityForm(false);notify("Opportunity added");await refresh()}}
  async function addProduct(){if(!productSku.trim()||!productName.trim()||!selectedOrgId)return;const{error}=await supabase.from("ln_products").upsert({org_id:selectedOrgId,sku:productSku.trim(),name:productName.trim(),stock_qty:Number(productStock)||0,reserved_qty:0},{onConflict:"org_id,sku"});if(error)notify(error.message);else{setProductSku("");setProductName("");setProductStock("0");setShowProductForm(false);notify("Product saved");await refresh()}}
  async function importProducts(file:File){if(!session||!selectedOrgId)return;setUploading(true);try{const form=new FormData();form.append("file",file);form.append("orgId",selectedOrgId);const res=await fetch("/api/platform/import-products",{method:"POST",headers:{Authorization:`Bearer ${session.access_token}`},body:form});const payload=await res.json().catch(()=>({}));if(!res.ok)throw new Error(String(payload.error||"Import failed"));notify(`${payload.count||0} products imported`);await refresh()}catch(e){notify(e instanceof Error?e.message:"Import failed")}finally{setUploading(false)}}

  function badge(status:string){const s=status.toLowerCase();const cls=s.includes("paid")||s.includes("awarded")||s.includes("ready")||s.includes("accepted")||s==="bid"?styles.badgeGood:s.includes("overdue")||s.includes("lost")||s.includes("cancel")||s.includes("escalated")?styles.badgeDanger:s.includes("review")||s.includes("partial")||s.includes("preparing")||s.includes("draft")?styles.badgeWarn:styles.badgeInfo;return <span className={`${styles.badge} ${cls}`}>{titleCase(status)}</span>}
  function ask(question:string){const q=question.trim().toLowerCase();if(!q)return;setAiQuestion(question);let answer="";if(q.includes("today")||q.includes("attention")||q.includes("focus")){const top=data.alerts.slice(0,4);answer=top.length?`Your highest-priority items are:\n${top.map((x,i)=>`${i+1}. ${x.title}${x.detail?` — ${x.detail}`:""}`).join("\n")}`:"There are no open priority alerts right now."}else if(q.includes("tender")||q.includes("bid")||q.includes("opportun")){const top=[...data.opportunities].filter((x)=>!["bid","no_bid","archived"].includes(x.status)).sort((a,b)=>b.bid_score-a.bid_score).slice(0,3);answer=top.length?`Best current bid candidates:\n${top.map((x,i)=>`${i+1}. ${x.title} — ${x.bid_score}% Bid score, ${x.match_score}% portfolio match, ${daysUntil(x.deadline_at)} days remaining.`).join("\n")}`:"No uncommitted opportunities are available."}else if(q.includes("supply")||q.includes("order")||q.includes("warehouse")||q.includes("stock")){answer=riskySupply.length?`${riskySupply.length} fulfilment line${riskySupply.length===1?" is":"s are"} not fully allocated. ${riskySupply.slice(0,3).map((x)=>`${x.item_name}: ${num(Number(x.allocated_qty))}/${num(Number(x.qty))} allocated`).join("; ")}.`:"All current supply lines are fully allocated."}else if(q.includes("cash")||q.includes("collect")||q.includes("invoice")||q.includes("receiv")){answer=`Open receivables are ${money(receivable)}. ${money(overdue)} is overdue. Based on invoices currently due within 30 days, ${money(cash30)} is expected in that window.`}else{answer=`LabNarrative currently sees ${data.opportunities.length} opportunities, ${data.tenders.length} active tender records, ${data.orders.length} orders and ${money(receivable)} in open receivables. Ask about priorities, bids, supply risk or cash collection for a focused answer.`}setAiAnswer(answer)}

  if(!authReady)return <main className={styles.loading}>Preparing LabNarrative…</main>;
  if(!session)return <main className={styles.page} data-theme={theme}><div className={styles.authPage}><section className={styles.authBrand}><div className={styles.wordmark}><span>Lab</span>Narrative</div><div><div className={styles.eyebrow}>Tender-to-cash operating system</div><h1>Find it. Win it. Deliver it. Collect it.</h1><p>One operating workspace from opportunity intelligence through tender execution, fulfilment, invoicing and collection.</p></div><div>Saudi / GCC · V1</div></section><section className={styles.authFlow}><div className={styles.authCard}><div className={styles.eyebrow}>{authMode==="signin"?"Secure workspace":"Create workspace account"}</div><h2>{authMode==="signin"?"Welcome back.":"Start with LabNarrative."}</h2><p>{authMode==="signin"?"Sign in to your company operating workspace.":"Create an account, then set up your organization."}</p><div className={styles.authForm}><label className={styles.field}><span>Email</span><input type="email" autoComplete="email" value={email} onChange={(e)=>setEmail(e.target.value)}/></label><label className={styles.field}><span>Password</span><input type="password" autoComplete={authMode==="signin"?"current-password":"new-password"} value={password} onChange={(e)=>setPassword(e.target.value)} onKeyDown={(e)=>{if(e.key==="Enter")void authenticate()}}/></label><button className={styles.buttonPrimary} onClick={()=>void authenticate()} disabled={authBusy}>{authBusy?"WORKING…":authMode==="signin"?"SIGN IN →":"CREATE ACCOUNT →"}</button>{authError?<div className={styles.authError}>{authError}</div>:null}</div><div className={styles.authSwitch}>{authMode==="signin"?"New to LabNarrative? ":"Already have an account? "}<button onClick={()=>{setAuthMode(authMode==="signin"?"signup":"signin");setAuthError("")}}>{authMode==="signin"?"Create account":"Sign in"}</button></div><div className={styles.formActions}><button className={styles.tinyButton} onClick={toggleTheme}>{theme==="light"?"Dark":"Light"}</button></div></div></section></div></main>;

  if(!organizations.length)return <main className={styles.page} data-theme={theme}><div className={styles.onboarding}><section className={styles.onboardingCard}><div className={styles.wordmark}><span>Lab</span>Narrative</div><div className={styles.eyebrow} style={{marginTop:24}}>Organization setup</div><h1>Create your operating workspace.</h1><p>This organization becomes the security boundary for products, opportunities, tenders, orders, warehouse, supply, invoices and collection. Other organizations cannot see its data.</p><div className={styles.formGrid} style={{marginTop:20}}><label className={styles.field}><span>Company name</span><input value={orgName} onChange={(e)=>setOrgName(e.target.value)} placeholder="Company name"/></label><label className={styles.field}><span>Industry</span><input value={orgIndustry} onChange={(e)=>setOrgIndustry(e.target.value)}/></label><label className={styles.field}><span>Country</span><input value={orgCountry} onChange={(e)=>setOrgCountry(e.target.value)}/></label><label className={styles.field}><span>Currency</span><input value="SAR" readOnly/></label></div><div className={styles.formActions}><button className={styles.button} onClick={()=>void signOut()}>Sign out</button><button className={styles.buttonPrimary} disabled={creatingOrg||!orgName.trim()} onClick={()=>void createOrganization()}>{creatingOrg?"CREATING…":"CREATE WORKSPACE →"}</button></div></section></div></main>;

  function PageHeader({title,copy,actions}:{title:string;copy:string;actions?:React.ReactNode}){return <div className={styles.pageHead}><div><div className={styles.eyebrow}>{T("LabNarrative operating workspace","مساحة تشغيل LabNarrative")}</div><h1>{title}</h1><p>{copy}</p></div>{actions?<div className={styles.headActions}>{actions}</div>:null}</div>}

  function Home(){return <><PageHeader title={T("Overview","نظرة عامة")} copy={T("What needs attention across the tender-to-cash workflow right now.","ما يحتاج إلى انتباهك الآن عبر رحلة المناقصة حتى التحصيل.")}/><section className={styles.hero}><article className={styles.heroMain}><div><div className={styles.eyebrow}>{T("Operating system","نظام التشغيل")}</div><h2>{T("From opportunity discovery to collected cash — one connected workflow.","من اكتشاف الفرصة إلى تحصيل المبلغ — مسار عمل واحد مترابط.")}</h2><p>{T("LabNarrative keeps tender intelligence, commercial execution, fulfilment and finance connected to the same business record.","يربط LabNarrative ذكاء الفرص والتنفيذ التجاري والتوريد والمالية بنفس السجل التشغيلي.")}</p></div><div className={styles.heroSummary}><span className={styles.heroPill}>{data.products.length} {T("products","منتجات")}</span><span className={styles.heroPill}>{data.opportunities.length} {T("opportunities","فرص")}</span><span className={styles.heroPill}>{data.tenders.length} {T("tenders","مناقصات")}</span><span className={styles.heroPill}>{data.orders.length} {T("orders","طلبات")}</span></div></article><article className={styles.attention}><div className={styles.attentionTop}><span>{T("Needs attention","يحتاج انتباه")}</span><b>{data.alerts.length}</b></div><div className={styles.attentionList}>{data.alerts.slice(0,4).map((x)=><div className={styles.attentionItem} key={x.id}><strong>{x.title}</strong><small>{x.detail||titleCase(x.type)}</small></div>)}{!data.alerts.length?<div className={styles.attentionItem}><strong>{T("All clear","لا توجد تنبيهات")}</strong><small>{T("No open operational alerts.","لا توجد تنبيهات تشغيلية مفتوحة.")}</small></div>:null}</div></article></section><section className={styles.metrics}><Metric label={T("Opportunity pipeline","قيمة الفرص")} value={money(opportunityValue)} hint={`${highMatch.length} ${T("high-match","عالية التطابق")}`}/><Metric label={T("Active tenders","المناقصات النشطة")} value={money(tenderValue)} hint={`${data.tenders.length} ${T("records","سجلات")}`}/><Metric label={T("Won / orders","القيمة الفائزة")} value={money(wonValue)} hint={`${data.orders.length} ${T("orders","طلبات")}`}/><Metric label={T("Receivables","المستحقات")} value={money(receivable)} hint={`${money(overdue)} ${T("overdue","متأخر")}`}/><Metric label={T("Cash next 30d","نقد متوقع 30 يوم")} value={money(cash30)} hint={T("based on invoice due dates","حسب تواريخ الاستحقاق")}/></section><section className={styles.grid2}><article className={styles.panel}><div className={styles.panelHead}><div><h3>{T("Best new opportunities","أفضل الفرص الجديدة")}</h3><p>{T("Ranked by portfolio match and Bid/No-Bid score.","مرتبة حسب تطابق المحفظة ودرجة قرار التقديم.")}</p></div><button className={styles.button} onClick={()=>setActive("opportunities")}>{T("View all","عرض الكل")}</button></div><div className={styles.panelBody}><div className={styles.cardList}>{highMatch.slice(0,3).map((x)=><div className={styles.card} key={x.id}><div className={styles.cardTop}><div><h4>{x.title}</h4><p>{x.buyer}</p></div><span className={styles.score}>{x.match_score}%</span></div><div className={styles.cardMeta}><span className={`${styles.badge} ${styles.badgeGood}`}>{x.recommendation||"BID"}</span><span className={styles.badge}>{daysUntil(x.deadline_at)} {T("days","يوم")}</span><span className={styles.badge}>{money(Number(x.estimated_value||0))}</span></div></div>)}{!highMatch.length?<div className={styles.empty}>{T("No high-match opportunities yet.","لا توجد فرص عالية التطابق بعد.")}</div>:null}</div></div></article><article className={styles.panel}><div className={styles.panelHead}><div><h3>{T("Operational alerts","التنبيهات التشغيلية")}</h3><p>{T("Tender, supply and collection risks in one list.","مخاطر المناقصات والتوريد والتحصيل في قائمة واحدة.")}</p></div><button className={styles.button} onClick={()=>setActive("ai")}>{T("Ask LabNarrative","اسأل LabNarrative")}</button></div><div className={styles.panelBody}><div className={styles.alertList}>{data.alerts.slice(0,5).map((x)=><div className={styles.alert} data-severity={x.severity} key={x.id}><i className={styles.alertDot}/><div><strong>{x.title}</strong><p>{x.detail}</p></div>{badge(x.severity)}</div>)}{!data.alerts.length?<div className={styles.empty}>{T("No open alerts.","لا توجد تنبيهات مفتوحة.")}</div>:null}</div></div></article></section></>}

  function Metric({label,value,hint}:{label:string;value:string;hint:string}){return <article className={styles.metric}><span>{label}</span><strong>{value}</strong><small>{hint}</small></article>}

  function Opportunities(){return <><PageHeader title={T("Opportunities","الفرص")} copy={T("Tender intelligence enters here. Review fit, evidence, deadline and Bid/No-Bid recommendation before committing team time.","يبدأ ذكاء المناقصات هنا. راجع التطابق والأدلة والموعد وتوصية التقديم قبل استهلاك وقت الفريق.")} actions={<button className={styles.buttonPrimary} onClick={()=>setShowOpportunityForm((v)=>!v)}>+ {T("Add opportunity","إضافة فرصة")}</button>}/>{showOpportunityForm?<div className={styles.formCard}><div className={styles.formGrid}><label className={styles.field}><span>{T("Buyer","الجهة")}</span><input value={opBuyer} onChange={(e)=>setOpBuyer(e.target.value)}/></label><label className={styles.field}><span>{T("Opportunity title","عنوان الفرصة")}</span><input value={opTitle} onChange={(e)=>setOpTitle(e.target.value)}/></label><label className={styles.field}><span>{T("Deadline","الموعد النهائي")}</span><input type="date" value={opDeadline} onChange={(e)=>setOpDeadline(e.target.value)}/></label><label className={styles.field}><span>{T("Estimated value","القيمة التقديرية")}</span><input type="number" value={opValue} onChange={(e)=>setOpValue(e.target.value)}/></label></div><div className={styles.formGrid} style={{marginTop:9}}><label className={styles.field}><span>{T("Portfolio match %","تطابق المحفظة %")}</span><input type="number" min="0" max="100" value={opMatch} onChange={(e)=>setOpMatch(e.target.value)}/></label></div><div className={styles.formActions}><button className={styles.button} onClick={()=>setShowOpportunityForm(false)}>{T("Cancel","إلغاء")}</button><button className={styles.buttonPrimary} onClick={()=>void addOpportunity()}>{T("Save opportunity","حفظ الفرصة")}</button></div></div>:null}<div className={styles.cardList}>{data.opportunities.map((x)=><article className={styles.card} key={x.id}><div className={styles.cardTop}><div><div className={styles.eyebrow}>{x.external_ref||titleCase(x.source)}</div><h4>{x.title}</h4><p>{x.buyer} · {dateLabel(x.deadline_at)} · {money(Number(x.estimated_value||0))}</p></div><span className={styles.score}>{x.match_score}%</span></div><div className={styles.cardMeta}>{badge(x.status)}<span className={`${styles.badge} ${x.bid_score>=80?styles.badgeGood:x.bid_score>=60?styles.badgeWarn:styles.badgeDanger}`}>{T("Bid score","درجة التقديم")} {x.bid_score}%</span><span className={styles.badge}>{x.matched_items}/{x.total_items||"—"} {T("items matched","بنود متطابقة")}</span><span className={styles.badge}>{daysUntil(x.deadline_at)} {T("days left","يوم متبقي")}</span></div>{x.summary?<p>{x.summary}</p>:null}<div className={styles.reasonList}>{reasons(x.reasons).map((r,i)=><div className={styles.reason} key={`${x.id}-${i}`}>{r}</div>)}</div><div className={styles.cardActions}>{x.status!=="bid"?<button className={styles.buttonPrimary} onClick={()=>void startBid(x.id)}>{T("Start bid","ابدأ التقديم")} →</button>:<button className={styles.button} onClick={()=>setActive("tenders")}>{T("Open tender","فتح المناقصة")} →</button>}{x.source_url?<a className={styles.button} href={x.source_url} target="_blank" rel="noreferrer">{T("Source","المصدر")} ↗</a>:null}</div></article>)}{!data.opportunities.length?<div className={styles.empty}>{T("No opportunities yet. Add one manually or connect an intelligence source.","لا توجد فرص بعد. أضف فرصة يدويًا أو اربط مصدر ذكاء.")}</div>:null}</div></>}

  function Tenders(){return <><PageHeader title={T("Tenders","المناقصات")} copy={T("Every committed opportunity becomes an execution workspace with readiness, missing requirements, quotation and award actions.","كل فرصة تم اعتمادها تتحول إلى مساحة تنفيذ تشمل الجاهزية والمتطلبات الناقصة وعرض السعر والنتيجة.")}/><div className={styles.panel}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>{T("Tender","المناقصة")}</th><th>{T("Buyer","الجهة")}</th><th>{T("Value","القيمة")}</th><th>{T("Deadline","الموعد")}</th><th>{T("Readiness","الجاهزية")}</th><th>{T("Status","الحالة")}</th><th>{T("Actions","الإجراءات")}</th></tr></thead><tbody>{data.tenders.map((x)=><tr key={x.id}><td><strong>{x.ref}</strong><small>{x.title}</small></td><td>{x.buyer}<small>{x.owner_name||T("Tender team","فريق المناقصات")}</small></td><td><strong>{money(Number(x.estimated_value||0))}</strong></td><td>{dateLabel(x.deadline_at)}<small>{daysUntil(x.deadline_at)} {T("days","يوم")}</small></td><td><div className={styles.progress}><i style={{width:`${x.readiness}%`}}/></div><small>{x.readiness}% · {x.missing_count} {T("missing","ناقص")}</small></td><td>{badge(x.status)}</td><td><div className={styles.cardActions}><button className={styles.button} onClick={()=>void createQuote(x.id)}>{T("Quote","عرض سعر")}</button>{x.status!=="submitted"&&x.status!=="awarded"?<button className={styles.button} onClick={()=>void setTenderStatus(x.id,"submitted")}>{T("Submitted","تم التقديم")}</button>:null}{x.status!=="awarded"?<button className={styles.buttonPrimary} onClick={()=>void awardTender(x.id)}>{T("Award","فوز")}</button>:null}</div></td></tr>)}</tbody></table>{!data.tenders.length?<div className={styles.empty}>{T("No tender workspaces yet. Start a bid from Opportunities.","لا توجد مساحات مناقصات بعد. ابدأ التقديم من صفحة الفرص.")}</div>:null}</div></div></>}

  function Quotations(){return <><PageHeader title={T("Quotations","عروض الأسعار")} copy={T("Commercial and technical validation before the bid leaves the company.","التحقق التجاري والفني قبل خروج العرض من الشركة.")}/><div className={styles.panel}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>{T("Quotation","العرض")}</th><th>{T("Customer","العميل")}</th><th>{T("Amount","القيمة")}</th><th>{T("Lines","البنود")}</th><th>{T("Validation","التحقق")}</th><th>{T("Status","الحالة")}</th><th>{T("Action","الإجراء")}</th></tr></thead><tbody>{data.quotations.map((x)=><tr key={x.id}><td><strong>{x.ref}</strong><small>{x.next_action||"—"}</small></td><td>{x.customer_name}</td><td><strong>{money(Number(x.amount))}</strong></td><td>{x.verified_count}/{x.items_count||"—"}<small>{x.error_count} {T("errors","أخطاء")}</small></td><td><div className={styles.progress}><i style={{width:`${x.items_count?Math.round((x.verified_count/x.items_count)*100):0}%`}}/></div></td><td>{badge(x.status)}</td><td>{!["sent","viewed","accepted"].includes(x.status)?<button className={styles.buttonPrimary} onClick={()=>void setQuoteStatus(x.id,"sent")}>{T("Mark sent","تسجيل الإرسال")}</button>:<span className={styles.badge}>{dateLabel(x.valid_until)}</span>}</td></tr>)}</tbody></table>{!data.quotations.length?<div className={styles.empty}>{T("No quotations yet. Create one from a tender.","لا توجد عروض أسعار بعد. أنشئ عرضًا من المناقصة.")}</div>:null}</div></div></>}

  function Orders(){return <><PageHeader title={T("Orders","الطلبات")} copy={T("Awarded business becomes an operational order that warehouse, supply and finance can follow together.","الأعمال الفائزة تتحول إلى طلب تشغيلي يتابعه المستودع والتوريد والمالية معًا.")}/><div className={styles.panel}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>{T("Order","الطلب")}</th><th>{T("Customer","العميل")}</th><th>{T("Amount","القيمة")}</th><th>{T("Fulfilment","التجهيز")}</th><th>{T("Due","الاستحقاق")}</th><th>{T("Status","الحالة")}</th><th>{T("Action","الإجراء")}</th></tr></thead><tbody>{data.orders.map((x)=><tr key={x.id}><td><strong>{x.ref}</strong><small>{x.items_count} {T("items","بنود")}</small></td><td>{x.customer_name}</td><td><strong>{money(Number(x.amount))}</strong></td><td>{x.ready_count}/{x.items_count}<small>{x.missing_count} {T("missing","ناقص")}</small></td><td>{dateLabel(x.due_at)}</td><td>{badge(x.status)}</td><td><div className={styles.cardActions}>{x.status!=="delivered"?<button className={styles.button} onClick={()=>void setOrderStatus(x.id,"delivered")}>{T("Delivered","تم التسليم")}</button>:null}<button className={styles.buttonPrimary} onClick={()=>void createInvoice(x.id)}>{T("Invoice","فاتورة")}</button></div></td></tr>)}</tbody></table>{!data.orders.length?<div className={styles.empty}>{T("No orders yet. Award a tender to create one.","لا توجد طلبات بعد. سجّل فوز مناقصة لإنشاء طلب.")}</div>:null}</div></div></>}

  function Warehouse(){return <><PageHeader title={T("Warehouse","المستودع")} copy={T("Live product availability against reservations and fulfilment demand.","توفر المنتجات مقابل المحجوز والكميات المطلوبة للتوريد.")} actions={<button className={styles.button} onClick={()=>setActive("products")}>{T("Manage products","إدارة المنتجات")}</button>}/><section className={styles.metrics}><Metric label={T("SKUs","المنتجات")} value={num(data.products.length)} hint={T("active catalog","كتالوج نشط")}/><Metric label={T("Units in stock","المتوفر")} value={num(sum(data.products.map((x)=>Number(x.stock_qty))))} hint={T("all products","كل المنتجات")}/><Metric label={T("Reserved","المحجوز")} value={num(sum(data.products.map((x)=>Number(x.reserved_qty))))} hint={T("committed stock","مخزون محجوز")}/><Metric label={T("Low availability","توفر منخفض")} value={num(shortageProducts.length)} hint={T("≤ 5 unreserved units","≤ 5 وحدات غير محجوزة")}/><Metric label={T("Supply risks","مخاطر التوريد")} value={num(riskySupply.length)} hint={T("not fully allocated","غير مكتمل التخصيص")}/></section><div className={styles.panel}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>SKU</th><th>{T("Product","المنتج")}</th><th>{T("Brand","العلامة")}</th><th>{T("Stock","المخزون")}</th><th>{T("Reserved","المحجوز")}</th><th>{T("Available","المتاح")}</th><th>{T("Status","الحالة")}</th></tr></thead><tbody>{data.products.map((x)=>{const available=Number(x.stock_qty)-Number(x.reserved_qty);return <tr key={x.id}><td><strong>{x.sku}</strong></td><td>{x.name}<small>{x.category||"—"}</small></td><td>{x.brand||"—"}</td><td>{num(Number(x.stock_qty))}</td><td>{num(Number(x.reserved_qty))}</td><td><strong>{num(available)}</strong></td><td>{available<=5?<span className={`${styles.badge} ${styles.badgeDanger}`}>{T("Low","منخفض")}</span>:<span className={`${styles.badge} ${styles.badgeGood}`}>{T("Available","متوفر")}</span>}</td></tr>})}</tbody></table></div></div></>}

  function SupplyView(){return <><PageHeader title={T("Supply","التوريد")} copy={T("Connect every delivery risk to the order and customer it affects.","اربط كل خطر توريد بالطلب والعميل المتأثر به.")}/><div className={styles.panel}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>{T("Order","الطلب")}</th><th>{T("Item","البند")}</th><th>{T("Required","المطلوب")}</th><th>{T("Allocated","المخصص")}</th><th>{T("Source","المصدر")}</th><th>{T("Due","الموعد")}</th><th>{T("Status","الحالة")}</th><th>{T("Action","الإجراء")}</th></tr></thead><tbody>{data.supply.map((x)=>{const order=data.orders.find((o)=>o.id===x.order_id);return <tr key={x.id}><td><strong>{order?.ref||"—"}</strong></td><td>{x.item_name}<small>{x.sku||"—"}</small></td><td>{num(Number(x.qty))}</td><td>{num(Number(x.allocated_qty))}</td><td>{x.source||"—"}</td><td>{dateLabel(x.due_at)}</td><td>{badge(x.status)}</td><td>{x.status!=="delivered"?<button className={styles.buttonPrimary} onClick={()=>void setSupplyStatus(x.id,"delivered")}>{T("Delivered","تم التسليم")}</button>:null}</td></tr>})}</tbody></table>{!data.supply.length?<div className={styles.empty}>{T("No supply lines yet.","لا توجد بنود توريد بعد.")}</div>:null}</div></div></>}

  function Invoices(){return <><PageHeader title={T("Invoices","الفواتير")} copy={T("Invoices remain connected to the order that generated them and the collection work that follows.","تبقى الفواتير مرتبطة بالطلب الذي أنشأها وبإجراءات التحصيل التالية.")}/><section className={styles.metrics}><Metric label={T("Invoiced","إجمالي الفواتير")} value={money(sum(data.invoices.map((x)=>Number(x.amount))))} hint={`${data.invoices.length} ${T("invoices","فواتير")}`}/><Metric label={T("Paid","المدفوع")} value={money(sum(data.invoices.map((x)=>Number(x.paid_amount))))} hint={T("recorded payments","دفعات مسجلة")}/><Metric label={T("Receivable","المستحق")} value={money(receivable)} hint={T("still open","لا يزال مفتوحًا")}/><Metric label={T("Overdue","المتأخر")} value={money(overdue)} hint={T("requires follow-up","يحتاج متابعة")}/><Metric label={T("Due within 30d","مستحق خلال 30 يوم")} value={money(cash30)} hint={T("cash planning","تخطيط السيولة")}/></section><div className={styles.panel}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>{T("Invoice","الفاتورة")}</th><th>{T("Customer","العميل")}</th><th>{T("Amount","القيمة")}</th><th>{T("Paid","المدفوع")}</th><th>{T("Due","الاستحقاق")}</th><th>{T("Status","الحالة")}</th><th>{T("Action","الإجراء")}</th></tr></thead><tbody>{data.invoices.map((x)=><tr key={x.id}><td><strong>{x.ref}</strong><small>{dateLabel(x.issued_at)}</small></td><td>{x.customer_name}</td><td><strong>{money(Number(x.amount))}</strong></td><td>{money(Number(x.paid_amount))}</td><td>{dateLabel(x.due_at)}</td><td>{badge(x.status)}</td><td>{x.status!=="paid"?<button className={styles.buttonPrimary} onClick={()=>void markInvoicePaid(x.id)}>{T("Record paid","تسجيل السداد")}</button>:null}</td></tr>)}</tbody></table>{!data.invoices.length?<div className={styles.empty}>{T("No invoices yet. Create one from an order.","لا توجد فواتير بعد. أنشئ فاتورة من طلب.")}</div>:null}</div></div></>}

  function CollectionView(){return <><PageHeader title={T("Collection","التحصيل")} copy={T("One queue for every open balance, owner, next action and escalation.","قائمة واحدة لكل رصيد مفتوح والمسؤول والإجراء التالي والتصعيد.")}/><div className={styles.cardList}>{data.collections.map((x)=>{const inv=data.invoices.find((i)=>i.id===x.invoice_id);const open=inv?Math.max(0,Number(inv.amount)-Number(inv.paid_amount)):0;return <article className={styles.card} key={x.id}><div className={styles.cardTop}><div><div className={styles.eyebrow}>{inv?.ref||"Invoice"}</div><h4>{inv?.customer_name||T("Customer","عميل")}</h4><p>{x.next_action||T("Follow up payment","متابعة السداد")}</p></div><strong>{money(open)}</strong></div><div className={styles.cardMeta}>{badge(x.status)}<span className={styles.badge}>{x.owner_name||T("Finance","المالية")}</span>{inv?.due_at?<span className={`${styles.badge} ${daysUntil(inv.due_at)<0?styles.badgeDanger:""}`}>{daysUntil(inv.due_at)<0?`${Math.abs(daysUntil(inv.due_at))} ${T("days overdue","يوم متأخر")}`:dateLabel(inv.due_at)}</span>:null}</div>{x.note?<p>{x.note}</p>:null}{inv&&inv.status!=="paid"?<div className={styles.cardActions}><button className={styles.buttonPrimary} onClick={()=>void markInvoicePaid(inv.id)}>{T("Record payment","تسجيل السداد")}</button></div>:null}</article>})}{!data.collections.length?<div className={styles.empty}>{T("No collection actions yet.","لا توجد إجراءات تحصيل بعد.")}</div>:null}</div></>}

  function Management(){const max=Math.max(opportunityValue,tenderValue,wonValue,receivable,1);return <><PageHeader title={T("Management","الإدارة")} copy={T("The executive view across commercial pipeline, execution risk and expected cash.","الرؤية التنفيذية عبر المسار التجاري ومخاطر التنفيذ والسيولة المتوقعة.")}/><section className={styles.metrics}><Metric label={T("Opportunity pipeline","مسار الفرص")} value={money(opportunityValue)} hint={`${data.opportunities.length} ${T("opportunities","فرص")}`}/><Metric label={T("Tender value","قيمة المناقصات")} value={money(tenderValue)} hint={`${data.tenders.length} ${T("active records","سجلات")}`}/><Metric label={T("Won value","قيمة الأعمال الفائزة")} value={money(wonValue)} hint={`${data.orders.length} ${T("orders","طلبات")}`}/><Metric label={T("Receivables","المستحقات")} value={money(receivable)} hint={`${money(overdue)} ${T("overdue","متأخر")}`}/><Metric label={T("Open alerts","التنبيهات") } value={num(data.alerts.length)} hint={T("across all departments","عبر جميع الأقسام")}/></section><section className={styles.grid2}><article className={styles.panel}><div className={styles.panelHead}><div><h3>{T("Commercial value flow","تدفق القيمة التجارية")}</h3><p>{T("A single view from discovery through cash collection.","رؤية واحدة من اكتشاف الفرصة حتى التحصيل.")}</p></div></div><div className={styles.panelBody}><div className={styles.pipeline}><Pipeline label={T("Opportunities","الفرص")} value={opportunityValue} max={max}/><Pipeline label={T("Tenders","المناقصات")} value={tenderValue} max={max}/><Pipeline label={T("Won / Orders","الفوز / الطلبات")} value={wonValue} max={max}/><Pipeline label={T("Receivables","المستحقات")} value={receivable} max={max}/></div></div></article><article className={styles.panel}><div className={styles.panelHead}><div><h3>{T("Management priorities","أولويات الإدارة")}</h3><p>{T("Highest-severity issues requiring cross-team attention.","أعلى المخاطر التي تتطلب اهتمامًا بين الفرق.")}</p></div></div><div className={styles.panelBody}><div className={styles.alertList}>{data.alerts.slice(0,6).map((x)=><div className={styles.alert} data-severity={x.severity} key={x.id}><i className={styles.alertDot}/><div><strong>{x.title}</strong><p>{x.detail}</p></div>{badge(x.severity)}</div>)}</div></div></article></section></>}
  function Pipeline({label,value,max}:{label:string;value:number;max:number}){return <div className={styles.pipelineRow}><span>{label}</span><div className={styles.bar}><i style={{width:`${Math.max(3,(value/max)*100)}%`}}/></div><b>{money(value)}</b></div>}

  function AI(){const prompts=[T("What needs my attention today?","ما الذي يحتاج انتباهي اليوم؟"),T("Which tenders should we bid on?","أي المناقصات يجب أن نتقدم لها؟"),T("Show supply risks","اعرض مخاطر التوريد"),T("How much cash is expected?","كم السيولة المتوقعة؟")];return <><PageHeader title={T("Ask LabNarrative","اسأل LabNarrative")} copy={T("V1 operational intelligence reads the same live workspace records used by every department.","ذكاء V1 التشغيلي يقرأ نفس سجلات العمل الحية التي تستخدمها جميع الأقسام.")}/><div className={styles.aiShell}><article className={styles.aiMain}><div className={styles.eyebrow}>LabNarrative AI · V1</div><h2>{T("Ask the business, not another dashboard.","اسأل عن العمل بدل التنقل بين لوحات المعلومات.")}</h2><p>{T("Ask about priorities, tender decisions, warehouse and supply risk, invoices or cash collection. V1 answers deterministically from your workspace data; generative reasoning can be layered on without changing the operating model.","اسأل عن الأولويات وقرارات المناقصات ومخاطر المستودع والتوريد والفواتير والتحصيل. يجيب V1 مباشرة من بيانات مساحة العمل.")}</p><div className={styles.aiInput}><input value={aiQuestion} onChange={(e)=>setAiQuestion(e.target.value)} onKeyDown={(e)=>{if(e.key==="Enter")ask(aiQuestion)}} placeholder={T("Ask LabNarrative…","اسأل LabNarrative…")}/><button className={styles.buttonPrimary} onClick={()=>ask(aiQuestion)}>{T("Ask","اسأل")}</button></div><div className={styles.promptChips}>{prompts.map((p)=><button className={styles.promptChip} key={p} onClick={()=>ask(p)}>{p}</button>)}</div>{aiAnswer?<div className={styles.aiAnswer}>{aiAnswer}</div>:null}</article><article className={styles.panel}><div className={styles.panelHead}><div><h3>{T("Live signals","الإشارات الحية")}</h3><p>{T("What the intelligence layer can see right now.","ما يراه نظام الذكاء الآن.")}</p></div></div><div className={styles.panelBody}><div className={styles.cardList}><div className={styles.card}><h4>{highMatch.length} {T("high-match opportunities","فرص عالية التطابق")}</h4><p>{T("Portfolio match of 80% or higher.","تطابق محفظة 80% أو أعلى.")}</p></div><div className={styles.card}><h4>{riskySupply.length} {T("supply risks","مخاطر توريد")}</h4><p>{T("Required quantity exceeds allocated quantity.","الكمية المطلوبة تتجاوز الكمية المخصصة.")}</p></div><div className={styles.card}><h4>{money(overdue)} {T("overdue","متأخر")}</h4><p>{T("Open invoices past their due date.","فواتير مفتوحة تجاوزت تاريخ الاستحقاق.")}</p></div></div></div></article></div></>}

  function Products(){return <><PageHeader title={T("Products","المنتجات")} copy={T("Your portfolio is the foundation for opportunity matching, tender line analysis, warehouse visibility and supply planning.","محفظة منتجاتك هي الأساس لمطابقة الفرص وتحليل بنود المناقصات ورؤية المستودع وتخطيط التوريد.")} actions={<button className={styles.buttonPrimary} onClick={()=>setShowProductForm((v)=>!v)}>+ {T("Add product","إضافة منتج")}</button>}/><div className={styles.dropZone}><div><strong>{T("Import product portfolio","استيراد محفظة المنتجات")}</strong><p>{T("Upload .xlsx or .csv. Supported columns: SKU, Name, Category, Brand, Stock, Reserved, Unit Cost, Sale Price.","ارفع ملف .xlsx أو .csv. الأعمدة المدعومة: SKU والاسم والفئة والعلامة والمخزون والمحجوز والتكلفة وسعر البيع.")}</p></div><input type="file" accept=".xlsx,.csv" disabled={uploading} onChange={(e)=>{const f=e.target.files?.[0];if(f)void importProducts(f);e.currentTarget.value=""}}/></div>{showProductForm?<div className={styles.formCard} style={{marginTop:12}}><div className={styles.formGrid}><label className={styles.field}><span>SKU</span><input value={productSku} onChange={(e)=>setProductSku(e.target.value)}/></label><label className={styles.field}><span>{T("Product name","اسم المنتج")}</span><input value={productName} onChange={(e)=>setProductName(e.target.value)}/></label><label className={styles.field}><span>{T("Stock","المخزون")}</span><input type="number" value={productStock} onChange={(e)=>setProductStock(e.target.value)}/></label></div><div className={styles.formActions}><button className={styles.button} onClick={()=>setShowProductForm(false)}>{T("Cancel","إلغاء")}</button><button className={styles.buttonPrimary} onClick={()=>void addProduct()}>{T("Save","حفظ")}</button></div></div>:null}<div className={styles.panel} style={{marginTop:12}}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>SKU</th><th>{T("Product","المنتج")}</th><th>{T("Category","الفئة")}</th><th>{T("Brand","العلامة")}</th><th>{T("Stock","المخزون")}</th><th>{T("Reserved","المحجوز")}</th><th>{T("Cost","التكلفة")}</th><th>{T("Sale","البيع")}</th></tr></thead><tbody>{data.products.map((x)=><tr key={x.id}><td><strong>{x.sku}</strong></td><td>{x.name}</td><td>{x.category||"—"}</td><td>{x.brand||"—"}</td><td>{num(Number(x.stock_qty))}</td><td>{num(Number(x.reserved_qty))}</td><td>{x.unit_cost==null?"—":money(Number(x.unit_cost))}</td><td>{x.sale_price==null?"—":money(Number(x.sale_price))}</td></tr>)}</tbody></table>{!data.products.length?<div className={styles.empty}>{T("No products yet. Import your portfolio to start matching opportunities.","لا توجد منتجات بعد. استورد محفظتك لبدء مطابقة الفرص.")}</div>:null}</div></div></>}

  const view=active==="home"?<Home/>:active==="opportunities"?<Opportunities/>:active==="tenders"?<Tenders/>:active==="quotations"?<Quotations/>:active==="orders"?<Orders/>:active==="warehouse"?<Warehouse/>:active==="supply"?<SupplyView/>:active==="invoices"?<Invoices/>:active==="collection"?<CollectionView/>:active==="management"?<Management/>:active==="ai"?<AI/>:<Products/>;

  return <main className={styles.page} data-theme={theme} dir={lang==="ar"?"rtl":"ltr"}><div className={styles.shell}><aside className={styles.sidebar}><div className={styles.brand}><div className={styles.wordmark}><span>Lab</span>Narrative</div><span className={styles.version}>V1</span></div><div className={styles.orgCard}><label>{T("Organization","المنشأة")}</label><select value={selectedOrgId} onChange={(e)=>setSelectedOrgId(e.target.value)}>{organizations.map((o)=><option value={o.id} key={o.id}>{o.name}</option>)}</select><div className={styles.orgMeta}>{selectedOrg?.industry||T("Business workspace","مساحة عمل")}</div></div><nav className={styles.nav}>{nav.map((x)=><div key={x.id}>{x.divider?<div className={styles.navDivider}/>:null}<button className={`${styles.navButton} ${active===x.id?styles.navButtonActive:""}`} onClick={()=>setActive(x.id)}><span className={styles.navIcon}>{x.icon}</span><span>{lang==="ar"?x.ar:x.en}</span></button></div>)}</nav><div className={styles.sidebarFoot}><div className={styles.role}>{T("Signed in","مسجل الدخول")}<b>{session.user.email}</b><span>{titleCase(currentRole)}</span></div><div className={styles.tinyActions}><button className={styles.tinyButton} onClick={()=>setLang((v)=>v==="en"?"ar":"en")}>{lang==="en"?"AR":"EN"}</button><button className={styles.tinyButton} onClick={toggleTheme}>{theme==="light"?T("Dark","داكن"):T("Light","فاتح")}</button><button className={styles.tinyButton} onClick={()=>void signOut()}>{T("Sign out","خروج")}</button></div></div></aside><section className={styles.main}><header className={styles.topbar}><div className={styles.mobileBrand}><span>Lab</span>Narrative</div><div className={styles.breadcrumb}>LabNarrative / <b>{lang==="ar"?currentView.ar:currentView.en}</b></div><div className={styles.topActions}><button className={styles.iconButton} onClick={()=>setLang((v)=>v==="en"?"ar":"en")}>{lang==="en"?"AR":"EN"}</button><button className={styles.iconButton} onClick={toggleTheme}>{theme==="light"?"☾":"☀"}</button><button className={styles.button} onClick={()=>void refresh()} disabled={loading}>{loading?T("Syncing…","مزامنة…"):T("Refresh","تحديث")}</button></div></header><div className={styles.content}>{view}{selectedOrg?.slug==="labnarrative-demo"?<div className={styles.disclaimer}>{T("Internal V1 demo workspace. All commercial records and values shown here are illustrative and do not represent a real company, tender, customer or transaction.","مساحة تجريبية داخلية لـ V1. جميع السجلات والقيم التجارية المعروضة توضيحية ولا تمثل شركة أو مناقصة أو عميلًا أو معاملة حقيقية.")}</div>:null}</div></section></div>{notice?<div className={styles.toast}>{notice}</div>:null}</main>;
}
